    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    best_versions = None
    best_score = None

    constraints = {name: tuple(bounds) for name, bounds in roots.items()}

    def is_acyclic(chosen):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True

            state[name] = 1
            for dep in chosen[name]['deps']:
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                dep_name = dep['name']
                if dep_name not in chosen or not visit(dep_name):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in chosen if state.get(name, 0) == 0)

    def search(chosen, required):
        nonlocal best_versions, best_score
        pending = required.keys() - chosen.keys()
        if not pending:
            if not is_acyclic(chosen):
                return
            score = tuple(
                chosen[name]['version'] if name in chosen else -1
                for name in names
            )
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {
                    name: row['version'] for name, row in chosen.items()
                }
            return

        name = min(pending)
        lower, upper = required[name]
        forbidden = blocked.get(name, ())
        pin = pins.get(name)

        for row in packages.get(name, []):
            version = row['version']
            if not lower <= version <= upper:
                continue
            if version in forbidden:
                continue
            if pin is not None and version != pin:
                continue

            next_chosen = dict(chosen)
            next_chosen[name] = row
            next_required = dict(required)
            feasible = True

            for dep in row['deps']:
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dep['name']
                dep_lower, dep_upper = dep['min'], dep['max']
                if dep_name in next_required:
                    old_lower, old_upper = next_required[dep_name]
                    dep_lower = max(old_lower, dep_lower)
                    dep_upper = min(old_upper, dep_upper)
                if dep_lower > dep_upper:
                    feasible = False
                    break
                next_required[dep_name] = (dep_lower, dep_upper)

                if dep_name in next_chosen:
                    dep_version = next_chosen[dep_name]['version']
                    if not dep_lower <= dep_version <= dep_upper:
                        feasible = False
                        break

            if feasible:
                search(next_chosen, next_required)

    search({}, constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
